// generated by tools/build_verse_manifests.js from ot_english.js — Dual-view English for the chapters of ot_verses/lam.js
registerEnglish([["Lamentations",1,1,"How does the city sit solitary, that was full of people! how is she become like a widow! she that was great among the nations, and princess among the provinces, how is she become a vassal!"],["Lamentations",1,2,"She weeps sore in the night, and her tears are on her cheeks: among all her lovers she has none to comfort her: all her friends have dealt treacherously with her, they have become her enemies."],["Lamentations",1,3,"Judah is gone into exile because of affliction, and because of great servitude: she dwells among the nations, she finds no rest: all her persecutors overtook her within the straits."],["Lamentations",1,4,"The ways of Zion do mourn, because none come to the solemn assembly: all her gates are desolate: her priests sigh, her virgins are afflicted, and she is in bitterness."],["Lamentations",1,5,"Her adversaries have become the chief, her enemies prosper; for the Lord has afflicted her for the multitude of her transgressions: her infants are gone into captivity before the enemy."],["Lamentations",1,6,"And from the daughter of Zion all her splendour is departed: her princes are become like harts that find no pasture, and they are gone without strength before the pursuer."],["Lamentations",1,7,"Jerusalem remembers in the days of her affliction and of her miseries all her pleasant things that she had in the days of old, when her people fell into the hand of the enemy, and none did help her: the adversaries saw her, and gloated at her destruction."],["Lamentations",1,8,"Jerusalem has grievously sinned; therefore she is become loathsome: all that honoured her despise her, because they have seen her nakedness: she herself also sighs, and turns backward."],["Lamentations",1,9,"Her filthiness was in her skirts; she took no thought of her last end; therefore she came down astonishingly: she has no comforter. O Lord, behold my affliction: for the enemy has magnified himself."],["Lamentations",1,10,"The adversary has spread out his hand upon all her pleasant things: for she has seen that heathen nations invade her sanctuary, those whom Thou didst forbid to enter into Thy congregation."],["Lamentations",1,11,"All her people sigh, they seek bread; they have given their pleasant things for food to relieve the soul: see, O Lord, and consider; how abject I am become."],["Lamentations",1,12,"Is it nothing to you, all you that pass by? behold, and see if there is any pain like my pain, which is done to me, with which the Lord has afflicted me in the day of his fierce anger."],["Lamentations",1,13,"From above he has sent fire into my bones, and it prevails against them: he has spread a net for my feet, he has turned me back: he has made me desolate and faint all the day."],["Lamentations",1,14,"The yoke of my transgressions is fastened on by his hand: they are knit together, and come up upon my neck: he has made my strength to fall, the Lord has delivered me into the hands of those against whom I am not able to rise up."],["Lamentations",1,15,"The Lord has spurned all my mighty men in the midst of me: he has called an assembly against me to crush my young men: the Lord has trodden the virgin, the daughter of Judah, as in a winepress."],["Lamentations",1,16,"For these things I weep; my eye, my eye runs down with water, because the comforter that should relieve my soul is far from me: my children are desolate, because the enemy has prevailed."],["Lamentations",1,17,"Zion spreads out her hands, and there is none to comfort her: the Lord has commanded against Jacob, adversaries round about him: Jerusalem is like a menstruous woman among them."],["Lamentations",1,18,"The Lord is righteous; for I have rebelled against his word: hear, I pray you, all the peoples, and behold my pain: my virgins and my young men are gone into captivity."],["Lamentations",1,19,"I called for my lovers, but they deceived me: my priests and my elders perished in the city, while they sought food for themselves to relieve their souls."],["Lamentations",1,20,"Behold, O Lord; for I am in distress: my bowels are troubled; my heart is turned within me; for I have grievously rebelled: abroad the sword bereaves, at home it is like death."],["Lamentations",1,21,"They have heard that I sigh: there is none to comfort me: all my enemies have heard of my trouble; they are glad that Thou hast done it: Thou wilt bring the day that Thou hast called, and they shall be like me."],["Lamentations",1,22,"Let all their wickedness come before Thee; and do to them, as Thou hast done to me for all my transgressions: for my sighs are many, and my heart is faint."],["Lamentations",2,1,"How has the Lord covered the daughter of Zion with a cloud in his anger, and cast down from heaven to earth the beauty of Israel, and remembered not his footstool in the day of his anger!"],["Lamentations",2,2,"The Lord has swallowed up without pity all the habitations of Jacob: he has thrown down in his wrath the strongholds of the daughter of Judah; he has brought them down to the ground: he has profaned the kingdom and its princes."],["Lamentations",2,3,"He has cut off in his fierce anger all the horn of Israel: he has drawn back his right hand from before the enemy, and he has burned against Jacob like a flaming fire, which devours round about."],["Lamentations",2,4,"He has bent his bow like an enemy: with his right hand set like an adversary, he has slain all that were pleasant to the eye: in the tent of the daughter of Zion, he has poured out his fury like fire."],["Lamentations",2,5,"The Lord was like an enemy: he has swallowed up Israel, he has swallowed up all her palaces: he has destroyed his strongholds, and has increased in the daughter of Judah mourning and lamentation."],["Lamentations",2,6,"And he has stripped his tabernacle, as if it were a garden: he has destroyed his place of assembly: the Lord has caused the appointed seasons and sabbaths to be forgotten in Zion, and has spurned in the indignation of his anger both king and priest."],["Lamentations",2,7,"The Lord has cast off his altar, he has abhorred his sanctuary, he has given up into the hand of the enemy the walls of her palaces; they have made a noise in the house of the Lord, as in the day of a solemn assembly."],["Lamentations",2,8,"The Lord has purposed to destroy the wall of the daughter of Zion: he has stretched out a line, he has not withdrawn his hand from destroying: therefore he made the rampart and the wall to lament; they languish together."],["Lamentations",2,9,"Her gates are sunk into the ground; he has destroyed and broken her bars: her king and her princes are among the nations: there is no law; her prophets also find no vision from the Lord."],["Lamentations",2,10,"The elders of the daughter of Zion sit upon the ground, and keep silence: they have cast up dust upon their heads; they have girded themselves with sackcloth: the virgins of Jerusalem hang down their heads to the ground."],["Lamentations",2,11,"My eyes fail with tears, my bowels are troubled, my liver is poured upon the earth, for the breach of the daughter of my people; because the children and the sucklings swoon in the broad places of the city."],["Lamentations",2,12,"They say to their mothers, Where is corn and wine? when they swoon like wounded men in the broad places of the city, when their soul is poured out into their mothers' bosom."],["Lamentations",2,13,"What shall I take to witness for thee? what shall I liken to thee, O daughter of Jerusalem? what shall I equal to thee, that I may comfort thee, O virgin daughter of Zion? for thy breach is great like the sea: who can heal thee?"],["Lamentations",2,14,"Thy prophets have seen for thee vain and foolish visions: and they have not exposed thy iniquity, to restore thy captivity; but have prophesied for thee burdens of falsehood and deceit."],["Lamentations",2,15,"All that pass by clap their hands at thee; they hiss and wag their head at the daughter of Jerusalem, saying, Is this the city that men call The perfection of beauty, The joy of the whole earth?"],["Lamentations",2,16,"All thy enemies have opened their mouth against thee: they hiss and gnash the teeth: they say, We have swallowed her up: certainly this is the day that we have looked for; we have found it, we have seen it."],["Lamentations",2,17,"The Lord has done that which he devised; he has fulfilled his word that he commanded in the days of old: he has thrown down without pity: and he has caused the enemy to rejoice over thee, he has raised up the horn of thy adversaries."],["Lamentations",2,18,"Their heart cried to the Lord. O wall of the daughter of Zion, let tears run down like a river day and night: give thyself no rest; let not the apple of thy eye cease."],["Lamentations",2,19,"Arise, cry out in the night: in the beginning of the watches pour out thy heart like water before the face of the Lord: lift up thy hands towards him for the life of thy young children, that faint for hunger at the head of every street."],["Lamentations",2,20,"Behold, O Lord, and consider to whom Thou hast done this. Shall the women eat their fruit, their cherished babes? shall priest and prophet be slain in the sanctuary of the Lord?"],["Lamentations",2,21,"Young and old lie on the ground in the streets: my virgins and my young men are fallen by the sword; Thou hast slain them in the day of Thy anger; Thou hast killed, and not pitied."],["Lamentations",2,22,"Thou hast called as in the day of a solemn assembly, my terrors round about, so that in the day of the Lord's anger none escaped or remained: those that I have cherished and brought up my enemy has consumed."],["Lamentations",3,1,"I am the man who has seen affliction by the rod of his wrath."],["Lamentations",3,2,"He has led me, and brought me into darkness, but not into light."],["Lamentations",3,3,"Surely he is turned against me; he turns his hand against me all the day."],["Lamentations",3,4,"He has made my flesh and my skin to waste away; he has broken my bones."],["Lamentations",3,5,"He has built a mound against me, and has beset me round about at head and hell."],["Lamentations",3,6,"He has set me in dark places, as those who are long ago dead."],["Lamentations",3,7,"He has hedged me about, so that I cannot get out: he has made my chain heavy."],["Lamentations",3,8,"Even when I cry and call for help, he stops up my prayer."],["Lamentations",3,9,"He has enclosed my ways with hewn stone, he has made my paths crooked."],["Lamentations",3,10,"He is to me like a bear lying in wait, and like a lion in secret places."],["Lamentations",3,11,"He has turned aside my ways, and pulled me in pieces: he has made me desolate."],["Lamentations",3,12,"He has bent his bow, and set me as a mark for the arrow."],["Lamentations",3,13,"He has caused the arrows of his quiver to enter into my reins."],["Lamentations",3,14,"I am become a derision to all my people; and their song all the day."],["Lamentations",3,15,"He has filled me with bitterness, he has sated me with wormwood."],["Lamentations",3,16,"He has also broken my teeth with gravel stones, he has pressed me down into the ashes."],["Lamentations",3,17,"My soul is far removed from peace: I have forgotten prosperity."],["Lamentations",3,18,"And I said, My strength and my hope are perished from the Lord."],["Lamentations",3,19,"Remember my affliction and my misery, the wormwood and the gall."],["Lamentations",3,20,"My soul has them still in remembrance, and is bowed down within me."],["Lamentations",3,21,"This I recall to my mind, therefore I have hope:"],["Lamentations",3,22,"that the Lord's steadfast love has not ceased, and that his compassions do not fail."],["Lamentations",3,23,"They are new every morning: great is thy faithfulness."],["Lamentations",3,24,"The Lord is my portion, says my soul; therefore I will hope in him."],["Lamentations",3,25,"The Lord is good to those who wait for him, to the soul that seeks him."],["Lamentations",3,26,"It is good that a man should quietly hope for the salvation of the Lord."],["Lamentations",3,27,"It is good for a man that he bear the yoke in his youth."],["Lamentations",3,28,"Let him sit alone and keep silence, because he has taken it upon him."],["Lamentations",3,29,"Let him put his mouth in the dust; perhaps there may be hope."],["Lamentations",3,30,"Let him offer his cheek to him who strikes him; let him take his fill of insult."],["Lamentations",3,31,"For the Lord will not cast off for ever:"],["Lamentations",3,32,"but though he cause grief, yet will he have compassion according to the abundance of his steadfast love."],["Lamentations",3,33,"For he does not willingly afflict or grieve the children of men."],["Lamentations",3,34,"To crush under foot all the prisoners of the earth,"],["Lamentations",3,35,"to turn aside the right of a man before the face of the most High,"],["Lamentations",3,36,"to subvert a man in his cause, the Lord approves not."],["Lamentations",3,37,"Who is he that says, and it comes to pass, when the Lord commands it not?"],["Lamentations",3,38,"Out of the mouth of the most High do not both good and evil come?"],["Lamentations",3,39,"Why then does a living man complain, a man for the punishment of his sins?"],["Lamentations",3,40,"Let us search and try our ways, and turn back to the Lord."],["Lamentations",3,41,"Let us lift up our heart with our hands to God in the heavens."],["Lamentations",3,42,"We have transgressed and have rebelled: Thou hast not pardoned."],["Lamentations",3,43,"Thou hast covered with anger, and pursued us: Thou hast slain, Thou hast not pitied."],["Lamentations",3,44,"Thou hast covered thyself with a cloud, so that prayer should not pass through."],["Lamentations",3,45,"Thou hast made us offscouring and refuse in the midst of the people."],["Lamentations",3,46,"All our enemies have opened their mouths wide against us."],["Lamentations",3,47,"Fear and the pit are come upon us, desolation and destruction."],["Lamentations",3,48,"My eye runs down with rivers of water for the breach of the daughter of my people."],["Lamentations",3,49,"My eye trickles down, and ceases not, without any intermission,"],["Lamentations",3,50,"till the Lord look down, and behold from heaven."],["Lamentations",3,51,"My eye affects my soul because of all the daughters of my city."],["Lamentations",3,52,"They chased me sore, like a bird, those who hate me without cause."],["Lamentations",3,53,"They have cut off my life in the dungeon, and have cast stones upon me."],["Lamentations",3,54,"Waters flowed over my head; then I said, I am cut off."],["Lamentations",3,55,"I called upon Thy name, O Lord, out of the nethermost pit."],["Lamentations",3,56,"Thou hast heard my voice: hide not Thy ear at my sighing, at my cry."],["Lamentations",3,57,"Thou didst draw near in the day that I called upon Thee: Thou didst say,"],["Lamentations",3,58,"Fear not. O Lord, Thou hast pleaded the causes of my soul; Thou hast redeemed my life."],["Lamentations",3,59,"O Lord, Thou hast seen my wrong: judge my cause."],["Lamentations",3,60,"Thou hast seen all their vengeance and all their devices against me."],["Lamentations",3,61,"Thou hast heard their insult, O Lord, and all their devices against me;"],["Lamentations",3,62,"the lips of those who rose up against me, and their muttering against me all the day."],["Lamentations",3,63,"Behold their sitting down, and their rising up; I am their song."],["Lamentations",3,64,"Render to them a recompense, O Lord, according to the work of their hands."],["Lamentations",3,65,"Give them sorrow of heart; Thy curse be on them!"],["Lamentations",3,66,"Pursue them in anger and destroy them from under the heavens of the Lord."],["Lamentations",4,1,"How is the gold become dim! how is the most fine gold changed! the hallowed stones are poured out at the top of every street."],["Lamentations",4,2,"The precious sons of Zion, comparable to fine gold, how are they esteemed as earthen pitchers, the work of the hands of the potter!"],["Lamentations",4,3,"Even the jackals draw out the breast, they give suck to their young ones: the daughter of my people is become cruel, like the ostriches in the wilderness."],["Lamentations",4,4,"The tongue of the sucking child cleaves to the roof of his mouth for thirst: the young children ask bread, and no man gives it to them."],["Lamentations",4,5,"They that did feed on dainties are desolate in the streets: they that were brought up in scarlet embrace dunghills."],["Lamentations",4,6,"For the doom of the daughter of my people is greater than the sin of Sodom, that was overthrown as in a moment, no hands being laid upon her."],["Lamentations",4,7,"Her Nazarites were purer than snow, they were whiter than milk, they were more ruddy in body than rubies, their polishing was as of sapphire:"],["Lamentations",4,8,"now their visage is blacker than coal; they are not known in the streets: their skin is shrivelled upon their bones; it is withered, it is become like a stick."],["Lamentations",4,9,"Those slain with the sword are better than those slain with hunger: for when pierced through, the former do ooze with the produce of the fields."],["Lamentations",4,10,"Hands of compassionate women have boiled their own children: they were their food in the destruction of the daughter of my people."],["Lamentations",4,11,"The Lord has accomplished his fury; he has poured out his fierce anger, and has kindled a fire in Zion and it has devoured its foundations."],["Lamentations",4,12,"The kings of the earth, and all the inhabitants of the world, would not have believed that the adversary and the enemy would enter the gates of Jerusalem."],["Lamentations",4,13,"It was for the sins of her prophets, and the iniquities of her priests, who shed the blood of the just in the midst of her."],["Lamentations",4,14,"They wandered blind through the streets, polluted with blood, so that none could touch their garments."],["Lamentations",4,15,"Away! unclean! they cried at them; away! away! do not touch. So they fled, and wandered away: among the nations it was said, They shall no longer sojourn here."],["Lamentations",4,16,"The anger of the Lord has divided them; he will no more regard them: they respected not the persons of the priests, they were not gracious to the elders."],["Lamentations",4,17,"As for us, our eyes do yet fail for our vain help: in our watching we have watched for a nation that could not save."],["Lamentations",4,18,"They hunt our steps, that we cannot walk in our broad places: our end is near, our days are fulfilled; for our end is come."],["Lamentations",4,19,"Our pursuers were swifter than the vultures in the sky: they chased us upon the mountains, they lay in wait for us in the wilderness."],["Lamentations",4,20,"The breath of our nostrils, the anointed of the Lord, was taken in their pits, of whom we said, Under his shadow we shall live among the nations."],["Lamentations",4,21,"Rejoice and be glad, O daughter of Edom, that dwellest in the land of Uz; the cup shall also pass over to thee: thou shalt be drunken, and strip thyself bare."],["Lamentations",4,22,"The punishment of thy iniquity is accomplished, O daughter of Zion; he will no more carry thee away into exile: he will visit thy iniquity, O daughter of Edom; he will uncover thy sins."],["Lamentations",5,1,"Remember, O Lord, what is come upon us: consider, and behold our insult."],["Lamentations",5,2,"Our inheritance is turned over to strangers, our houses to aliens."],["Lamentations",5,3,"We are become orphans and fatherless, our mothers are like widows."],["Lamentations",5,4,"We have drunk our water for money; our own wood is sold to us."],["Lamentations",5,5,"We are pursued to our necks: we labour, and have no rest."],["Lamentations",5,6,"We have given the hand to Egypt, and to Assyria, to be satisfied with bread."],["Lamentations",5,7,"Our fathers have sinned, and are no more; but we bear their iniquities."],["Lamentations",5,8,"Servants rule over us: there is none to deliver us out of their hand."],["Lamentations",5,9,"We get our bread with the peril of our lives because of the sword of the wilderness."],["Lamentations",5,10,"Our skin is hot like an oven because of the burning famine."],["Lamentations",5,11,"Women are ravished in Zion, and maidens in the cities of Judah."],["Lamentations",5,12,"Princes are hanged up by their hand: the faces of elders are not honoured."],["Lamentations",5,13,"Young men drag the millstone, and youths stumble under the wood."],["Lamentations",5,14,"The elders have ceased from the gate, the young men from their music."],["Lamentations",5,15,"The joy of our heart is ceased; our dance is turned into mourning."],["Lamentations",5,16,"The crown is fallen from our head: woe to us, that we have sinned!"],["Lamentations",5,17,"For this our heart is faint; for these things our eyes are dim."],["Lamentations",5,18,"Because of the mountain of Zion, which is desolate, foxes prowl over it."],["Lamentations",5,19,"Thou, O Lord, art enthroned forever; Thy throne is from generation to generation."],["Lamentations",5,20,"Why dost Thou forget us forever, why dost Thou so long forsake us?"],["Lamentations",5,21,"Turn us to Thee, O Lord, and we shall be turned; renew our days as of old:"],["Lamentations",5,22,"unless Thou hast utterly rejected us; and art exceedingly angry against us."]]);
